1|/**
2| * Hello Tool - Minimal custom tool example
3| *
4| * Demonstrates using ExtensionAPI's logger and injected schema builder.
5| */
6|import type { ExtensionAPI } from "@oh-my-pi/pi-coding-agent";
7|
8|export default function (pi: ExtensionAPI) {
9|	const z = pi.zod;
10|
11|	pi.registerTool({
12|		name: "hello",
