1|// extensions/vansrouter.ts
2|// OMP-native VansRouter provider extension.
3|//
4|// Multi-tier:
5|//   Discovery:  dynamic /v1/models -> disk cache (3 rotations) -> seed list
6|//   Health:     /api/health -> /v1/models -> TCP connect -> unregistered
7|//   Resilience: /api/breaker + /api/quota/kimchi + /api/proxies -> status only
8|//   ACL:        /api/key/info -> unfiltered on failure
9|//   Write:      rotate main -> bak1 -> bak2, then atomic rename
10|//
11|// Uses pi.registerProvider + fetchDynamicModels + ctx.ui.* only.
12|// No createProvider. No @earendil-works/* or @mariozechner/*.
13|
14|import type { ExtensionAPI } from "@oh-my-pi/pi-coding-agent";
15|import { promises as fsp } from "node:fs";
16|import path from "node:path";
17|import os from "node:os";
18|import net from "node:net";
19|
20|const VR_BASE = process.env.VANSROUTER_URL ?? process.env.NINEROUTER_URL ?? "http://127.0.0.1:20128";
21|const VR_KEY_ENV = "VANSROUTER_API_KEY";
22|const VR_KEY_FALLBACK_ENV = "NINEROUTER_KEY";
23|
24|const CACHE_DIR = path.join(os.homedir(), ".omp", "agent", "cache");
25|const CATALOG_MAIN = path.join(CACHE_DIR, "vansrouter-catalog.json");
26|const CATALOG_BAK1 = path.join(CACHE_DIR, "vansrouter-catalog.bak1.json");
27|const CATALOG_BAK2 = path.join(CACHE_DIR, "vansrouter-catalog.bak2.json");
28|const RESILIENCE_CACHE = path.join(CACHE_DIR, "vansrouter-resilience.json");
29|
30|const HTTP_TIMEOUT_MS = 3000;
31|const HEALTH_TIMEOUT_MS = 1500;
32|const DISCOVERY_TIMEOUT_MS = 8000;
33|
34|const SEED_MODELS = [
35|  { id: "oc/jev-1.13-free", name: "OpenCode Jev Free", contextWindow: 128000, maxTokens: 8192 },
36|  { id: "oc/mimo-v2.5-free", name: "OpenCode Mimo Free", contextWindow: 128000, maxTokens: 8192 },
37|  { id: "oc/nemotron-3.5-lightning-free", name: "OpenCode Nemotron Lightning Free", contextWindow: 128000, maxTokens: 8192 },
38|  { id: "oc/deepseek-v4-flash-free", name: "OpenCode DeepSeek Flash Free", contextWindow: 128000, maxTokens: 8192 },
39|  { id: "mmf/mimo-auto", name: "MMF Mimo Auto", contextWindow: 128000, maxTokens: 8192 },
40|];
41|
42|interface ModelEntry { id: string; name: string; contextWindow: number; maxTokens: number; }
43|interface Catalog { fetchedAt: number; source: "dynamic" | "cache-main" | "cache-bak1" | "cache-bak2" | "seed"; models: ModelEntry[]; }
44|interface ResilienceStatus {
45|  fetchedAt: number;
46|  breaker: { open?: number } | null;
47|  quota: { daysUntilReset?: number } | null;
48|  proxies: { dead?: number; pools?: number } | null;
49|  acl: { allowedProviders?: string[]; allowedKinds?: string[] } | null;
50|}
51|
52|async function httpJson<T>(url: string, init: RequestInit = {}, timeoutMs = HTTP_TIMEOUT_MS): Promise<T | null> {
53|  try {
54|    const res = await fetch(url, { ...init, signal: AbortSignal.timeout(timeoutMs) });
55|    if (!res.ok) return null;
56|    return (await res.json()) as T;
57|  } catch { return null; }
58|}
59|
60|function authHeaders(key: string): Record<string, string> {
61|  return key ? { Authorization: "Bearer " + key } : {};
62|}
63|
64|async function probeHealth(base: string): Promise<boolean> {
65|  const h = await httpJson<{ ok?: boolean }>(base + "/api/health", {}, HEALTH_TIMEOUT_MS);
66|  if (h && h.ok !== false) return true;
67|  const m = await httpJson<unknown>(base + "/v1/models", {}, HEALTH_TIMEOUT_MS);
68|  if (m) return true;
69|  return tcpProbe(base);
70|}
71|
72|function tcpProbe(base: string): Promise<boolean> {
73|  return new Promise((resolve) => {
74|    try {
75|      const u = new URL(base);
76|      const port = Number(u.port || (u.protocol === "https:" ? 443 : 80));
77|      const sock = net.connect({ host: u.hostname, port }, () => { sock.destroy(); resolve(true); });
78|      sock.on("error", () => { sock.destroy(); resolve(false); });
79|      sock.setTimeout(1500, () => { sock.destroy(); resolve(false); });
80|    } catch { resolve(false); }
81|  });
82|}
83|
84|async function fetchCatalogDynamic(base: string, key: string): Promise<ModelEntry[] | null> {
85|  const body = await httpJson<{ data?: Array<Record<string, unknown>> }>(base + "/v1/models", { headers: authHeaders(key) }, DISCOVERY_TIMEOUT_MS);
86|  if (!body?.data || !Array.isArray(body.data)) return null;
87|  const seen = new Set<string>();
88|  const out: ModelEntry[] = [];
89|  for (const raw of body.data) {
90|    const id = typeof raw.id === "string" ? raw.id : null;
91|    if (!id || seen.has(id)) continue;
92|    seen.add(id);
93|    out.push({
94|      id,
95|      name: typeof raw.name === "string" ? raw.name : id,
96|      contextWindow: typeof raw.context_window === "number" ? raw.context_window : typeof raw.contextWindow === "number" ? raw.contextWindow : 128000,
97|      maxTokens: typeof raw.max_tokens === "number" ? raw.max_tokens : typeof raw.maxTokens === "number" ? raw.maxTokens : 8192,
98|    });
99|  }
100|  return out.length ? out : null;
101|}
102|
103|async function readCatalogFromDisk(): Promise<Catalog | null> {
104|  const files: Array<[string, Catalog["source"]]> = [[CATALOG_MAIN, "cache-main"], [CATALOG_BAK1, "cache-bak1"], [CATALOG_BAK2, "cache-bak2"]];
105|  for (const [f, src] of files) {
106|    try {
107|      const parsed = JSON.parse(await fsp.readFile(f, "utf8")) as Partial<Catalog>;
108|      if (Array.isArray(parsed.models) && parsed.models.length > 0) {
109|        return { fetchedAt: typeof parsed.fetchedAt === "number" ? parsed.fetchedAt : 0, source: src, models: parsed.models as ModelEntry[] };
110|      }
111|    } catch {}
112|  }
113|  return null;
114|}
115|
116|async function writeCatalogWithBackup(catalog: Catalog): Promise<void> {
117|  await fsp.mkdir(CACHE_DIR, { recursive: true });
118|  try { await fsp.copyFile(CATALOG_MAIN, CATALOG_BAK1); } catch {}
119|  try { await fsp.copyFile(CATALOG_BAK1, CATALOG_BAK2); } catch {}
120|  const tmp = CATALOG_MAIN + ".tmp";
121|  await fsp.writeFile(tmp, JSON.stringify(catalog, null, 2), { mode: 0o600 });
122|  await fsp.rename(tmp, CATALOG_MAIN);
123|}
124|
125|async function resolveCatalog(base: string, key: string): Promise<Catalog> {
126|  const dyn = await fetchCatalogDynamic(base, key);
127|  if (dyn) {
128|    const c: Catalog = { fetchedAt: Date.now(), source: "dynamic", models: dyn };
129|    await writeCatalogWithBackup(c);
130|    return c;
131|  }
132|  const cached = await readCatalogFromDisk();
133|  if (cached) return cached;
134|  return { fetchedAt: Date.now(), source: "seed", models: SEED_MODELS };
135|}
136|
137|async function probeResilience(base: string, key: string): Promise<ResilienceStatus> {
138|  const h = authHeaders(key);
139|  const [b, q, p, a] = await Promise.allSettled([
140|    httpJson<ResilienceStatus["breaker"]>(base + "/api/breaker", { headers: h }),
141|    httpJson<ResilienceStatus["quota"]>(base + "/api/quota/kimchi", { headers: h }),
142|    httpJson<ResilienceStatus["proxies"]>(base + "/api/proxies", { headers: h }),
143|    httpJson<ResilienceStatus["acl"]>(base + "/api/key/info", { headers: h }),
144|  ]);
145|  const pick = <T>(r: PromiseSettledResult<T | null>): T | null => r.status === "fulfilled" ? r.value : null;
146|  const status: ResilienceStatus = { fetchedAt: Date.now(), breaker: pick(b), quota: pick(q), proxies: pick(p), acl: pick(a) };
147|  try {
148|    await fsp.mkdir(CACHE_DIR, { recursive: true });
149|    await fsp.writeFile(RESILIENCE_CACHE, JSON.stringify(status, null, 2), { mode: 0o600 });
150|  } catch {}
151|  return status;
152|}
153|
154|function applyAclFilter(models: ModelEntry[], acl: ResilienceStatus["acl"]): ModelEntry[] {
155|  if (!acl) return models;
156|  const { allowedProviders } = acl;
157|  if (!allowedProviders) return models;
158|  return models.filter((m) => allowedProviders.includes(m.id.split("/")[0]));
159|}
160|
161|function formatStatusLine(catalog: Catalog, status: ResilienceStatus | null): string {
162|  const parts: string[] = [];
163|  const tag = catalog.source === "dynamic" ? "" : catalog.source.startsWith("cache") ? " (" + catalog.source.replace("cache-", "") + ")" : " (seed)";
164|  parts.push("VR:" + catalog.models.length + tag);
165|  if (status?.breaker?.open) parts.push(status.breaker.open + " tripped");
166|  if (status?.quota?.daysUntilReset) parts.push(status.quota.daysUntilReset + "d reset");
167|  if (status?.proxies?.dead) parts.push(status.proxies.dead + " dead");
168|  return parts.join(" - ");
169|}
170|
171|export default function vansrouterExtension(pi: ExtensionAPI) {
172|  let lastCatalog: Catalog | null = null;
173|  let lastStatus: ResilienceStatus | null = null;
174|
175|  function resolveKey(): string {
176|    return process.env[VR_KEY_ENV] ?? process.env[VR_KEY_FALLBACK_ENV] ?? "";
177|  }
178|
179|  async function syncAndRegister(ctx: any, reason: string): Promise<void> {
180|    const healthy = await probeHealth(VR_BASE);
181|    if (!healthy) {
182|      ctx.ui?.notify?.("VansRouter unreachable at " + VR_BASE + " (" + reason + ")", "warn");
183|      return;
184|    }
185|    const catalog = await resolveCatalog(VR_BASE, resolveKey());
186|    lastCatalog = catalog;
187|    const status = await probeResilience(VR_BASE, resolveKey());
188|    lastStatus = status;
189|    const filtered = applyAclFilter(catalog.models, status.acl);
190|    const visible = filtered.length ? filtered : catalog.models;
191|    pi.registerProvider("vansrouter", {
192|      baseUrl: VR_BASE + "/v1",
193|      apiKey: VR_KEY_ENV,
194|      api: "openai-completions",
195|      authHeader: true,
196|      fetchDynamicModels: async (apiKey: string) => {
197|        const dyn = await fetchCatalogDynamic(VR_BASE, apiKey);
198|        if (dyn) {
199|          const fd = applyAclFilter(dyn, lastStatus?.acl ?? null);
200|          const vis = fd.length ? fd : dyn;
201|          lastCatalog = { fetchedAt: Date.now(), source: "dynamic", models: vis };
202|          await writeCatalogWithBackup(lastCatalog);
203|          return vis;
204|        }
205|        return visible;
206|      },
207|    });
208|    try { ctx.ui?.setStatus?.("vansrouter", formatStatusLine(catalog, status)); } catch {}
209|  }
210|
211|  pi.on("session_start", async (_e: unknown, ctx: any) => { await syncAndRegister(ctx, "session_start"); });
212|
213|  pi.registerCommand?.("vansrouter", {
214|    description: "VansRouter provider control",
215|    handler: async (args: string, ctx: any) => {
216|      const sub = (args || "").trim().split(/\\s+/)[0] || "status";
217|      if (sub === "status") {
218|        const cat = lastCatalog ?? (await readCatalogFromDisk()) ?? { fetchedAt: 0, source: "seed" as const, models: SEED_MODELS };
219|        ctx.ui?.notify?.(formatStatusLine(cat, lastStatus) + "\\nbase: " + VR_BASE + "\\nkey: " + (resolveKey() ? "present" : "MISSING") + "\\nmodels: " + cat.models.map((m) => m.id).join(", "), "info");
220|        return;
221|      }
222|      if (sub === "sync") { await syncAndRegister(ctx, "manual sync"); ctx.ui?.notify?.("VansRouter catalog resynced", "info"); return; }
223|      if (sub === "repair") {
224|        await writeCatalogWithBackup({ fetchedAt: Date.now(), source: "seed", models: SEED_MODELS });
225|        await syncAndRegister(ctx, "repair");
226|        ctx.ui?.notify?.("VansRouter cache repaired", "info");
227|        return;
228|      }
229|      if (sub === "cache") {
230|        const tiers = await Promise.all([CATALOG_MAIN, CATALOG_BAK1, CATALOG_BAK2].map(async (f) => {
231|          try { const s = await fsp.stat(f); return path.basename(f) + ": " + s.size + "B @ " + new Date(s.mtimeMs).toISOString(); }
232|          catch { return path.basename(f) + ": (absent)"; }
233|        }));
234|        ctx.ui?.notify?.(tiers.join("\\n"), "info");
235|        return;
236|      }
237|      ctx.ui?.notify?.("usage: /vansrouter [status|sync|repair|cache]", "info");
238|    },
239|  });
240|
241|  pi.on("session_end", async () => {
242|    if (lastCatalog) { try { await writeCatalogWithBackup(lastCatalog); } catch {} }
243|  });
244|}

