		baseUrl: VR_BASE + "/v1",
		apiKey: VR_KEY_ENV,
		api: "openai-completions",
		authHeader: true,
		autoRefresh: false,
	});

	pi.on("session_start", async (_e: unknown, ctx: ExtensionContext) => {
		await syncAndRegister(ctx, "session_start");
	});

	pi.on("session_end", async () => {
		if (lastCatalog) {
			try { await writeCatalogWithBackup(lastCatalog); } catch { /* continue */ }
		}
	});

	// Command interface
	pi.registerCommand?.("vansrouter", {
		description: "VansRouter provider control",
		handler: async (args: string, ctx: ExtensionContext) => {
			const sub = (args || "").trim().split(/\s+/)[0] || "status";

			if (sub === "status") {
				const cat = lastCatalog ?? (await readCatalogFromDisk()) ?? { fetchedAt: 0, source: "seed", models: SEED_MODELS };
				ctx.ui.notify(
					formatStatusLine(cat, lastStatus) + "\n" +
					"base: " + VR_BASE + "\n" +
					"key: " + (resolveKey() ? "present" : "MISSING") + "\n" +
					"models: " + cat.models.map((m) => m.id).join(", "),
					"info"
				);
				return;
			}

			if (sub === "sync") {
				await syncAndRegister(ctx, "manual sync");
				ctx.ui.notify("VansRouter catalog resynced", "info");
				return;
			}

			if (sub === "repair") {
				await writeCatalogWithBackup({ fetchedAt: Date.now(), source: "seed", models: SEED_MODELS });
				await syncAndRegister(ctx, "repair");
				ctx.ui.notify("VansRouter cache repaired", "info");
				return;
			}

			if (sub === "cache") {
				const tiers = await Promise.all([CATALOG_MAIN, CATALOG_BAK1, CATALOG_BAK2].map(async (f) => {
					try {
						const s = await fsp.stat(f);
						return path.basename(f) + ": " + s.size + "B @ " + new Date(s.mtimeMs).toISOString();
					} catch {
						return path.basename(f) + ": (absent)";
					}
				}));
				ctx.ui.notify(tiers.join("\n"), "info");
				return;
			}

			ctx.ui.notify("usage: /vansrouter [status|sync|repair|cache]", "info");
		},
	});
}

